// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _withdrawAmount, uint256 _depositAmount) public {
        vm.assume(_depositAmount > 0);
        vm.assume(_withdrawAmount > _depositAmount);
        vm.deal(address(c), _depositAmount);
        bool ok;
        try c.withdraw(_withdrawAmount) { ok = true; } catch { ok = false; }
        assertTrue(ok == false);
    }
}
